fn add_bytes(value: &mut usize, amount: usize) -> Result<(), ValueError> { *value = value.checked_add(amount).ok_or_else(|| ValueError::new(ValueRefusalKind::OwnershipLimit, "JSON relational size overflow"))?; Ok(()) }
